CREATE TABLE `territorio_departamento` (
  `id` int(11) NOT NULL,
  `codigo_dane` char(2) DEFAULT NULL,
  `nombre` varchar(120) NOT NULL,
  `capital` varchar(120) DEFAULT NULL,
  `poblacion` bigint(20) DEFAULT NULL,
  `superficie` decimal(14,2) DEFAULT NULL,
  `region` varchar(80) DEFAULT NULL,
  `prefijo_telefonico` varchar(10) DEFAULT NULL,
  `descripcion` text DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  `actualizado_en` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_depto_nombre` (`nombre`),
  KEY `idx_depto_dane` (`codigo_dane`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
