--
-- Table structure for table `territorio_municipio`
--

DROP TABLE IF EXISTS `territorio_municipio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `territorio_municipio` (
  `id` int(11) NOT NULL,
  `departamento_id` int(11) NOT NULL,
  `codigo_dane` char(5) DEFAULT NULL,
  `nombre` varchar(120) NOT NULL,
  `poblacion` bigint(20) DEFAULT NULL,
  `superficie` decimal(14,2) DEFAULT NULL,
  `codigo_postal` varchar(20) DEFAULT NULL,
  `descripcion` text DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `creado_en` datetime NOT NULL DEFAULT current_timestamp(),
  `actualizado_en` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_muni_depto` (`departamento_id`),
  KEY `idx_muni_nombre` (`nombre`),
  KEY `idx_muni_dane` (`codigo_dane`),
  CONSTRAINT `fk_muni_depto` FOREIGN KEY (`departamento_id`) REFERENCES `territorio_departamento` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

