DROP TABLE IF EXISTS `territorio_sincronizacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `territorio_sincronizacion` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fecha_inicio` datetime NOT NULL,
  `fecha_fin` datetime DEFAULT NULL,
  `estado` enum('EN_PROCESO','EXITOSA','FALLIDA') NOT NULL DEFAULT 'EN_PROCESO',
  `departamentos_nuevos` int(11) NOT NULL DEFAULT 0,
  `departamentos_actualizados` int(11) NOT NULL DEFAULT 0,
  `municipios_nuevos` int(11) NOT NULL DEFAULT 0,
  `municipios_actualizados` int(11) NOT NULL DEFAULT 0,
  `duracion_ms` bigint(20) DEFAULT NULL,
  `mensaje` varchar(500) DEFAULT NULL,
  `usuario` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sync_fecha` (`fecha_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

